import { Message } from '../foundation';
import { ChatCompletion, Choice, ChatCompletionToolCalls, ChatCompletionToolCall, ChatCompletionCustomToolCall } from './interface';
/* 
Chat Completion VS. Response
- The former only have content、refusal、function_call、tool_calls; 
- The former annotations belongs to content;
- The former function_call and tool_calls do not have call_id and status;
*/
export default function chatCompletionToMessage(chatCompletion: ChatCompletion): Message[] {
    return chatCompletion.choices.map((choice: Choice) => {
        const message = choice.message;
        const role = message.role;
        const id = chatCompletion.id;
        const status = 'completed'; 

        const outputResult = [];

        // processing text and refusal
        if (message.content !== '' || message.refusal !== '') {
            const annotations = (message.annotations?.length
                ? message.annotations.map((annotation) => ({
                    type: annotation.type,
                    ...(annotation.url_citation || {}),
                }))
                : []);

            const outputMessage = [
                message.content !== '' && {
                    type: 'output_text',
                    text: message.content,
                    annotations,
                },
                message.refusal !== '' && {
                    type: 'refusal',
                    refusal: message.refusal,
                },
            ].filter(Boolean);

            outputResult.push({
                type: 'message',
                id: id,
                role: 'assistant',
                status: status,
                content: outputMessage
            });
        }

        // processing function call
        if (message.function_call) {
            outputResult.push({
                ...message.function_call,
                type: 'function_call',
                status: 'completed',
            });
        }

        // processing tool calls
        if (message?.tool_calls?.length) {
            const toolCalls = message.tool_calls.map((toolCall: ChatCompletionToolCalls) => {
                if (toolCall.type === 'function') {
                    return {
                        status: 'completed',
                        ...(toolCall as ChatCompletionToolCall).function,
                        type: 'function_call',
                        // todo: call_id?
                    };
                }
                return {
                    ...(toolCall as ChatCompletionCustomToolCall).custom,
                    type: 'custom_call',
                };
            });
            outputResult.push(...toolCalls);
        }

        // Currently, the Response API does not support voice output, but chat completion does.
        if (message.audio) {
            outputResult.push({
                type: 'audio',
                ...message.audio,
            });
        }

        return {
            id: id,
            role: role,
            content: outputResult,
            status: status,
        };
    });
}

import { AudioContentPart, ChatCompletionInput, ImageContentPart, FileContentPart, TextInput } from './interface';
export default function chatInputToChatCompletion(inputContent: any): ChatCompletionInput { // todo: 合入 aiChatInput 后补充类型定义
    const { references, attachments, inputContents, setup } = inputContent;

    let inputs: (ImageContentPart | AudioContentPart | FileContentPart | TextInput)[] = [];

    if (attachments?.length) { // todo: attachment 允许传递目录？
        attachments.forEach((item: any) => {
            const { name, url } = item;
            if (name.includes('.png') || name.includes('.jpg') || name.includes('.jpeg')) {
                inputs.push({
                    type: 'image_url',
                    image_url: {
                        url: url,
                    },
                });
            } else {
                // Inputs by file URL are not supported for chat completions. Use the ResponsesAPI for this option.
                inputs.push({
                    type: 'file',
                    file: {
                        file_data: item.file_data,
                        filename: name,
                        file_id: item?.id,
                    },
                });
            }
        });
    }

    if (inputContents?.length) {
        inputContents.forEach((item: any) => {
            inputs.push({
                type: 'text',
                text: item.text,
            });
        });
    }

    return {
        role: "user",
        messages: [{
            role: "user",
            content: inputs,
        }],
        model: setup?.model,
        references,
        setup: setup ?? {}
    };

}

import { MessageContent } from "../../aiChatInput/interface";


export default function chatInputToMessage(inputContent: MessageContent) { 
    const { references, attachments, inputContents, setup } = inputContent;

    let inputs: any[] = [];

    if (attachments?.length) { 
        attachments.forEach((item: any) => {
            const { name, url } = item;
            if (name.includes('.png') || name.includes('.jpg') || name.includes('.jpeg')) {
                inputs.push({
                    ...item,
                    type: 'input_image',
                    image_url: url,
                    detail: 'auto',
                });
            } else {
                inputs.push({
                    ...item,
                    type: 'input_file',
                    file_url: url, 
                    filename: name,
                });
            }
        });
    }

    if (inputContents?.length) {
        inputContents.forEach((item: any) => {
            inputs.push({
                type: 'input_text',
                text: item.text,
            });
        });
    }

    return {
        role: "user",
        content: [{
            type: 'message',
            role: 'user',
            content: inputs,
        }],
        model: setup?.model,
        references,
        setup: setup ?? {}
    };
}

