                .#{$prefix}-select-selection {
                    color: $color-aiChatInput_rich_text-select_selection-text;
                    font-weight: bold;
                    margin-left: $spacing-aiChatInput_rich_text-select_selection-marginLeft;

                }

                .#{$prefix}-select-arrow {
