        const {
            defaultActiveKey,
            activeKey,
            accordion
        } = this.getProps();
        let activeKeyList = activeKey ? activeKey : defaultActiveKey;
        if (accordion) {
            activeKeyList = Array.isArray(activeKeyList) ? activeKeyList[0] : activeKeyList;
        }
        if (activeKeyList && activeKeyList.length) {
