/**
 * @file
 * Date-related formatting display method
 */
import { format } from 'date-fns';
import { strings } from '../constants';
import { BaseValueType } from '../foundation';

/**
 * Formats the displayed date text
 * @param {string[]|Date[]} values
 * @param {string} formatToken
 * @param {Object} groupOptions
 * @param {Object} locale
 * @returns {string}
 */
export function formatDateValues(
    values: BaseValueType[],
    formatToken: string,
    {
        groupInnerSeparator = strings.DEFAULT_SEPARATOR_RANGE as string,
        groupSize = 1,
        groupSeparator = strings.DEFAULT_SEPARATOR_MULTIPLE as string,
    } = {},
    locale: any
) {
    let text = '';
    (groupSize <= 0 || typeof groupSize !== 'number') && (groupSize = 1);
    // console.log(values, formatToken, groupInnerSeparator, groupSize, groupSeparator);

    if (Array.isArray(values) && values.length) {
        const groups = [];
        const { length } = values;
        // chunk
        for (let i = 0; i < length; i++) {
            if (i % groupSize === 0) {
                groups.push([]);
            }
            const curArrIdx = Math.floor(i / groupSize);
            groups[curArrIdx].push(values[i]);
        }

        text = groups
            .map(arr =>
                arr
                    .map(v => {
                        if (v) {
                            // console.log(`formatDateValues() -> formatDateValues: ${v}`);
                            return format(v, formatToken, { locale });
                        } else {
                            return '';
                        }
                    })
                    .join(groupInnerSeparator)
            )
            .join(groupSeparator);
    }
    return text;
}

/**
 *
 * @param {number} weekStartsOn
 * the index of the first day of the week （0-Sunday，1-Monday, etc）
 *
 */

type WeekStartNumber = 0 | 1 | 2 | 3 | 4 | 5 | 6;
const getDayofWeek = ({ weekStartsOn = 0 }: { weekStartsOn: WeekStartNumber }) => {
    const weekDay = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    for (let index = 0; index < weekStartsOn; index++) {
        weekDay.push(weekDay.shift());
    }
    return weekDay;
};
export default getDayofWeek;

import { strings } from '../constants';

const defaultFormatTokens = {
    date: strings.FORMAT_FULL_DATE,
    dateTime: strings.FORMAT_DATE_TIME,
    dateRange: strings.FORMAT_FULL_DATE,
    dateTimeRange: strings.FORMAT_DATE_TIME,
    month: strings.FORMAT_YEAR_MONTH,
    monthRange: strings.FORMAT_YEAR_MONTH,
} as const;

const getDefaultFormatToken = (type: string) => defaultFormatTokens;

export function getDefaultFormatTokenByType(type: string) {
    return type && defaultFormatTokens[type];
}

export default getDefaultFormatToken;

import { addMonths, Locale as dateFnsLocale } from 'date-fns';
import isValidDate from './isValidDate';
import { compatibleParse } from './parser';
import isTimestamp from './isTimestamp';

/**
 * get left panel picker date and right panel picker date
 */
export default function getDefaultPickerDate(options: GetDefaultPickerValueDateOptions) {
    const { defaultPickerValue, format, dateFnsLocale } = options;
    let nowDate = Array.isArray(defaultPickerValue) ? defaultPickerValue[0] : defaultPickerValue;
    let nextDate = Array.isArray(defaultPickerValue) ? defaultPickerValue[1] : undefined;

    switch (true) {
        case isValidDate(nowDate):
            break;
        case isTimestamp(nowDate):
            nowDate = new Date(nowDate);
            break;
        case typeof nowDate === 'string':
            nowDate = compatibleParse(nowDate as string, format, undefined, dateFnsLocale);
            break;
        default:
            nowDate = new Date();
            break;
    }

    switch (true) {
        case isValidDate(nextDate):
            break;
        case isTimestamp(nextDate):
            nextDate = new Date(nextDate);
            break;
        case typeof nextDate === 'string':
            nextDate = compatibleParse(nextDate as string, format, undefined, dateFnsLocale);
            break;
        default:
            nextDate = addMonths(nowDate as Date, 1);
            break;
    }

    return {
        nowDate: nowDate as Date,
        nextDate: nextDate as Date,
    };
}

type BaseValueType = string | number | Date;

interface GetDefaultPickerValueDateOptions {
    defaultPickerValue?: BaseValueType | BaseValueType[];
    format: string;
    dateFnsLocale: dateFnsLocale
}

import { isFunction } from 'lodash';
import { strings } from '../constants';
import { format } from 'date-fns';

/**
 * Calculate the date string offset from the date
 * @param {*} fn
 * @param {*} date
 */
const getFullDateOffset = (fn: any, date: any) => {
    if (!date) {
        return '';
    }
    const getDate = new Date(date);
    const offsetDate = isFunction(fn) ? fn(getDate) : getDate;
    return format(new Date(offsetDate), strings.FORMAT_FULL_DATE);
};

export default getFullDateOffset;

import { strings } from '../constants';
import { getDefaultFormatTokenByType } from './getDefaultFormatToken';

/**
 * 获取 insetInput 输入框的 placeholder
 * Get the placeholder of the insetInput input
 * 
 * If type is time related, we only recognize the format like `dateFormat timeFormat`
 *  - 'yyyy-MM-dd HH:mm:ss' // ok
 *  - 'yyyy-MM-dd  HH:mm:ss' // bad format
 * 
 * @example
 * 'yyyy-MM-dd' => 'yyyy-MM-dd'
 * 'yyyy-MM' => 'yyyy-MM'
 * 'yyyy-MM-dd HH:mm:ss' => 'yyyy-MM-dd HH:mm:ss'
 * 'yyyy-MM-dd HH:mm' => 'yyyy-MM-dd HH:mm'
 * 'Pp' => 'yyyy-MM-dd'
 */
export default function getInsetInputFormatToken(options: { format: string; type: typeof strings.TYPE_SET[number] }) {
    const { format, type } = options;
    const dateReg = /([yMd]{0,4}[^a-z\s]*[yMd]{0,4}[^a-z\s]*[yMd]{0,4})/i;
    const dateTimeReg = /([yMd]{0,4}[^a-z\s]*[yMd]{0,4}[^a-z\s]*[yMd]{0,4}) (H{0,2}[^a-z\s]*m{0,2}[^a-z\s]*s{0,2})/i;
    const defaultToken = getDefaultFormatTokenByType(type);
    let insetInputFormat: string;

    switch (type) {
        case 'dateTime':
        case 'dateTimeRange':
            const dateTimeResult = dateTimeReg.exec(format);
            insetInputFormat = (dateTimeResult && dateTimeResult[1] && dateTimeResult[2]) ? `${dateTimeResult[1]} ${dateTimeResult[2]}` : defaultToken;
            break;
        case 'date':
        case 'month':
        case 'monthRange':
        case 'dateRange':
        default:
            const dateResult = dateReg.exec(format);
            insetInputFormat = dateResult && dateResult[1] || defaultToken;
            break;
    }

    return insetInputFormat;
}

import { strings } from '../constants'; 

/**
 * 从 insetInputStr 字符串解析出 insetInputValue 对象
 * Parse the insetInputValue object from the insetInputStr string
 * 
 * @example
 * ```
 * '2022-02-01' => { monthLeft: { dateInput: '2022-02-01' } }
 * '2022-02-01 00:00:00' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00' } }
 * '2022-02-01 00:00:00 ~ 2022-02-15 00:00:00' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00'}, monthRight: { dateInput: '2022-02-15', timeInput: '00:00:00' } }
 * 
 * '2022-0' => { monthLeft: { dateInput: '2022-0' } }
 * '2022-02-01 00:00:' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:' } }
 * '2022-02-01 00:00:00 ~ ' => { monthLeft: { dateInput: '2022-02-01', timeInput: '00:00:00'}, monthRight: { dateInput: '', timeInput: '' } }
 * ' ~ 2022-02-15 00:00:00' => { monthLeft: { dateInput: '', timeInput: '' }, monthRight: { dateInput: '2022-02-15', timeInput: '00:00:00' } }
 * ```
 */
export default function getInsetInputValueFromInsetInputStr(options: { inputValue: string; rangeSeparator: string; type: typeof strings.TYPE_SET[number] }) {
    const timeSeparator = ' ';
    const { inputValue = '', rangeSeparator, type } = options;
    let leftDateInput, leftTimeInput, rightDateInput, rightTimeInput;
    const insetInputValue = {
        monthLeft: {
            dateInput: '',
            timeInput: '',
        },
        monthRight: {
            dateInput: '',
            timeInput: '',
        }
    };

    switch (type) {
        case 'date':
        case 'month':
        case 'monthRange':
            insetInputValue.monthLeft.dateInput = inputValue;
            break;
        case 'dateRange':
            [leftDateInput = '', rightDateInput = ''] = inputValue.split(rangeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthRight.dateInput = rightDateInput;
            break;
        case 'dateTime':
            [leftDateInput = '', leftTimeInput = ''] = inputValue.split(timeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthLeft.timeInput = leftTimeInput;
            break;
        case 'dateTimeRange':
            const [leftInput = '', rightInput = ''] = inputValue.split(rangeSeparator);
            [leftDateInput = '', leftTimeInput = ''] = leftInput.split(timeSeparator);
            [rightDateInput = '', rightTimeInput = ''] = rightInput.split(timeSeparator);
            insetInputValue.monthLeft.dateInput = leftDateInput;
            insetInputValue.monthLeft.timeInput = leftTimeInput;
            insetInputValue.monthRight.dateInput = rightDateInput;
            insetInputValue.monthRight.timeInput = rightTimeInput;
            break;
    }
    return insetInputValue;
}

/**
 *
 * @param {string} month
 */
import {
    startOfMonth,
    lastDayOfMonth,
    getDaysInMonth,
    // getDay,
    // parseISO,
    format
} from 'date-fns';

function formatFullDate(year: number | string = '', month: number | string = '', day: number | string = ''): string {
    let dateStr = '';
    const monthFull = typeof month === 'number' && month < 10 ? `0${ month}` : month.toString();
    const dayNumberFull = typeof day === 'number' && day < 10 ? `0${ day}` : day.toString();
    dateStr = `${String(year) }-${ monthFull }-${ dayNumberFull}`;
    return dateStr;
}

/**
 * [getWeeks description]
 */
export type WeekStartNumber = 0 | 1 | 2 | 3 | 4 | 5 | 6;
function getWeeks(date: Date, weekStartsOn: WeekStartNumber = 0) {
    const weekDayNotInMonth = {
        dayNumber: '',
        dateNumberFull: '',
        fullDate: '',
    }; // For the first or last week epmtyDays
    const daysInMonth = getDaysInMonth(date); // Get the total number of days in the month
    const year = format(date, 'yyyy');
    const month = format(date, 'MM');
    const lastday = lastDayOfMonth(date); // Get the last day of the month
    const firstDay = startOfMonth(date); // Get the first day of the month
    // Const firstDayInWeek = getDay (firstDay);//The first day belongs to the day of the week
    // What is the first day of the month in the first row?
    const firstDayInWeek = Number(format(firstDay, 'e', { weekStartsOn }));

    const weeks = [];
    let week = [];
    // add empty days to set first day in correct position
    for (let s = 1; s < firstDayInWeek; s++) {
        week.push(weekDayNotInMonth);
    }

    for (let d = 0; d < daysInMonth; d++) {
        const dayNumber = d + 1;
        const dayNumberFull = dayNumber < 10 ? `0${ dayNumber}` : dayNumber.toString();
        const fullDate = formatFullDate(year, month, dayNumber);

        week.push({
            dayNumber,
            dayNumberFull,
            fullDate,
        });

        if (week.length === 7) {
            weeks.push(week);
            week = [];
        } else if (fullDate === format(lastday, 'yyyy-MM-dd')) {
            // Last week alone
            weeks.push(week);
            week = [];
        }
    }
    return weeks;
}

const getMonthTable = (month: Date, weekStartsOn: WeekStartNumber) => {
    const weeks = getWeeks(month, weekStartsOn);
    const monthText = format(month, 'yyyy-MM');
    return { monthText, weeks, month };
};

export default getMonthTable;

export { formatFullDate };

export default function getYearAndMonth(year: { left: number; right: number }, month: { left: number; right: number }) {
    const nowYear = new Date().getFullYear();
    const nowMonth = new Date().getMonth();

    const rightMonth = month.right || (nowMonth + 2);
    const rightYear = year.right || (rightMonth <= 12 ? nowYear : nowYear + 1);

    return {
        year: { left: year.left || nowYear, right: rightYear },
        month: { left: month.left || nowMonth + 1, right: rightMonth <= 12 ? rightMonth : 1 },
    };
}

const getYears = (startYear?: number, endYear?: number) => {
    const currentYear = new Date().getFullYear();
    let start = typeof startYear === 'number' ? startYear : currentYear - 100;
    let end = typeof endYear === 'number' ? endYear : currentYear + 100;
    if (end < start) {
        [start, end] = [end, start];
    }
    return Array.from({ length: end - start + 1 }, (v, i) => start + i);
};
export default getYears;

import isAfter from './isAfter';
import isBefore from './isBefore';
import isBetween from './isBetween';
import isWithinInterval from './isWithinInterval';
import isSameDay from './isSameDay';

import isTimestamp from './isTimestamp';
import isUnixTimestamp from './isUnixTimestamp';
import isValidDate from './isValidDate';
import getDefaultFormatToken from './getDefaultFormatToken';
import getYears from './getYears';
import getMonthsInYear from './getMonthsInYear';
import getFullDateOffset from './getFullDateOffset';
import getYearAndMonth from './getYearAndMonth';

export {
    isAfter,
    isBefore,
    isBetween,
    isWithinInterval,
    isSameDay,
    isTimestamp,
    isUnixTimestamp,
    isValidDate,
    getDefaultFormatToken,
    getYears,
    getMonthsInYear,
    getFullDateOffset,
    getYearAndMonth
};

import { isAfter as dateFnsIsAfter, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isAfter(date: string | Date, dateToCompare: string | Date) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsAfter(dayOne, dayTwo);
}

import { isBefore as dateFnsIsBefore, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isBefore(date: Date | string, dateToCompare: Date | string) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsBefore(dayOne, dayTwo);
}

import { isWithinInterval, parseISO, isEqual, isBefore } from 'date-fns';
import isString from '../../utils/isString';

/**
 * is the date between start and end?(not including start and end)
 *   - if start > end, return false
 * @param {String|Date} day
 * @param {Object} { start: string|Date, end: string|Date}
 * @returns {Boolean}
 */
export default function isBetween(day: string | Date, { start, end }: { start: string | Date; end: string | Date }) {
    const d = isString(day) ? parseISO(day) : day;
    const s = isString(start) ? parseISO(start) : start;
    const e = isString(end) ? parseISO(end) : end;
    return isBefore(s, e) && isWithinInterval(d, { start: s, end: e }) && !isEqual(d, s) && !isEqual(d, e);
}

export default function isDate(date: any) {
    return Object.prototype.toString.call(date) === '[object Date]';
}

import { isSameDay as dateFnsIsSameDay, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isSameDay(date: string | Date, dateToCompare: string | Date) {
    const dayOne = isString(date) ? parseISO(date) : date;
    const dayTwo = isString(dateToCompare) ? parseISO(dateToCompare) : dateToCompare;
    return dateFnsIsSameDay(dayOne, dayTwo);
}

import isValidDate from './isValidDate';
import isNumber from '../../utils/isNumber';

export default function isTimestamp(ts: any) {
    return isNumber(ts) && isValidDate(new Date(ts));
}

import isNumber from '../../utils/isNumber';
import isValidDate from './isValidDate';

export default function isUnixTimestamp(ts: any) {
    return isNumber(ts) && ts.toString().length === 10 && isValidDate(new Date(ts * 1000));
}

export default function isValidDate(date: any) {
    return date && Object.prototype.toString.call(date) === '[object Date]' && !isNaN(date as any);
}

export default function isValidTimeZone(timeZone?: string | number) {
    return ['string', 'number'].includes(typeof timeZone) && timeZone !== '';
}

import { isWithinInterval as dateFnsIsWithinInterval, parseISO } from 'date-fns';
import isString from '../../utils/isString';

export default function isWithinInterval(day: string | Date, { start, end }: { start: string | Date; end: string | Date }) {
    const d = isString(day) ? parseISO(day) : day;
    const s = isString(start) ? parseISO(start) : start;
    const e = isString(end) ? parseISO(end) : end;
    return dateFnsIsWithinInterval(d, { start: s, end: e });
}

/**
 * @file
 * Various date-related analysis methods
 */
import { isValid, parseISO, parse, Locale } from 'date-fns';

/**
 * Parsing value to Date object
 */
export function compatibleParse(
    value: string,
    formatToken?: string,
    baseDate?: Date,
    locale?: Locale
): Date | null {
    let result = null;
    if (value) {
        if (formatToken) {
            baseDate = baseDate || new Date();
            result = parse(value, formatToken, baseDate, { locale });
        }
        if (!isValid(result)) {
            result = parseISO(value);
        }
        if (!isValid(result)) {
            result = new Date(Date.parse(value));
        }
        const yearInvalid = isValid(result) && String(result.getFullYear()).length > 4;
        if (!isValid(result) || yearInvalid) {
            result = null;
        }
    }
    return result;
}


/**
 * whether value can be parsed with date-fns `parse`
 * 
 * @example
 * isValueParseValid({ value: '2021-01-01', formatToken: 'yyyy-MM-dd' }); // true
 * isValueParseValid({ value: '2021-01-0', formatToken: 'yyyy-MM-dd' }); // false
 * isValueParseValid({ value: '2021-01', formatToken: 'yyyy-MM-dd' }); // false
 */
export function isValueParseValid(options: {
    value: string;
    formatToken: string;
    baseDate?: Date;
    locale?: Locale
}) {
    const { value, locale, formatToken } = options;
    const baseDate = options.baseDate || new Date();
    const result = parse(value, formatToken, baseDate, { locale });
    return isValid(result);
}

