.#{$module} {
    box-sizing: border-box;
    max-width: $width-popconfirm-maxWidth;

    &-inner {
        display: flex;
        flex-direction: column;
        padding: $spacing-popconfirm-top $spacing-popconfirm-top $spacing-popconfirm-top $spacing-popconfirm-bottom;
        position: relative;
    }

    &-header {
        display: flex;
        justify-content: flex-start;

        &-title {
            @include font-size-header-6;
            font-weight: $font-popconfirm_header_title-fontWeight;
            margin-bottom: $spacing-popconfirm_header_title-marginBottom;
            color: $color-popconfirm_header-text;
        }

        &-icon {
            width: $width-popconfirm-icon;
            height: $width-popconfirm-icon;
            margin-right: $spacing-popconfirm_header_icon-marginRight;
        }

        .#{$prefix}-icon {

            &-alert_triangle {
                color: $color-popconfirm_header_alert-icon;
            }
        }

        &-body {
            display: inline-flex;
            flex-grow: 1;
            flex-direction: column;
        }
    }

    &-body {
        color: $color-popconfirm_body-text;

        &-withIcon {
            margin-left: $width-popconfirm-icon + $spacing-popconfirm_header_icon-marginRight;
        }

        & > p {
            margin: $spacing-popconfirm_body_p-margin;
            padding: $spacing-popconfirm_body_p-padding;
        }
    }

    &-footer {
        margin-top: $spacing-popconfirm_footer-marginTop;
        display: flex;
        justify-content: flex-end;

        & > .#{$prefix}-button:first-child:not(:last-child) {
            margin-right: $spacing-popconfirm_footer_btn-marginRight;
        }
    }

    // The border-radius is defined separately in the component, the default value is the same as popover

    &-popover {
        border-radius: $radius-popconfirm-popover;
    }
}

.#{$prefix}-popover-with-arrow {
    .#{$module}-inner {
        padding: $spacing-popconfirm_popover_with_arrow_inner-padding;
    }
}

@import './rtl.scss';

import { get } from 'lodash';

import BaseFoundation, { DefaultAdapter } from '../base/foundation';
import isPromise from '../utils/isPromise';

export interface PopconfirmAdapter<P = Record<string, any>, S = Record<string, any>> extends DefaultAdapter<P, S> {
    setVisible: (visible: boolean) => void;
    updateConfirmLoading: (loading: boolean) => void;
    updateCancelLoading: (loading: boolean) => void;
    notifyConfirm: (e: any) => Promise<any> | void;
    notifyCancel: (e: any) => Promise<any> | void;
    notifyVisibleChange: (visible: boolean) => void;
    notifyClickOutSide: (e: any) => void;
    focusCancelButton: () => void;
    focusOkButton: () => void;
    focusPrevFocusElement: () => void
}

export default class PopConfirmFoundation<P = Record<string, any>, S = Record<string, any>> extends BaseFoundation<PopconfirmAdapter<P, S>, P, S> {

    init(): void {}

    destroy(): void {}

    handleCancel(e: any): void {
        const maybePromise = this._adapter.notifyCancel(e) as Promise<any>;
        if (isPromise(maybePromise)) {
            this._adapter.updateCancelLoading(true);
            maybePromise.then(
                (result: any) => {
                    this.handleVisibleChange(false);
                    this._adapter.updateCancelLoading(false);
                },
                (errors: any) => {
                    this._adapter.updateCancelLoading(false);
                }
            );
        } else {
            this.handleVisibleChange(false);
        }
    }

    handleConfirm(e: any): void {
        const maybePromise = this._adapter.notifyConfirm(e) as Promise<any>;
        if (isPromise(maybePromise)) {
            this._adapter.updateConfirmLoading(true);
            maybePromise.then(
                (result: any) => {
                    this._adapter.updateConfirmLoading(false);
                    this.handleVisibleChange(false);
                },
                (errors: any) => {
                    this._adapter.updateConfirmLoading(false);
                }
            );
        } else {
            this.handleVisibleChange(false);
        }
    }

    handleClickOutSide(e: any): void {
        this._adapter.notifyClickOutSide(e);
    }

    handleVisibleChange(visible: boolean): void {
        if (!this._isControlledComponent('visible')) {
            this._adapter.setVisible(visible);
        }
        if (visible) {
            this.handleFocusOperateButton();
        } else {
            this._adapter.focusPrevFocusElement();
        }
        this._adapter.notifyVisibleChange(visible);
    }

    handleFocusOperateButton() {
        const { cancelButtonProps, okButtonProps } = this._adapter.getProps() as any;
        if (get(cancelButtonProps, 'autoFocus') && !get(cancelButtonProps, 'disabled')) {
            this._adapter.focusCancelButton();
        } else if (get(okButtonProps, 'autoFocus') && !get(okButtonProps, 'disabled')) {
            this._adapter.focusOkButton();
        }
    }
}

