    constructor(adapter: ContainerAdapter) {
        super({ ...ContainerFoundation.defaultAdapter, ...adapter });
    }

    init = () => {};

    destroy = () => {
        this.afterHide();
    };

    handleCancel(e: any) {
        this._adapter.notifyCancel(e);
    }

    beforeShow() {
        this._adapter.setOnKeyDownListener();
    }

    afterHide() {
        this._adapter.removeKeyDownListener();
    }

