$module: #{$prefix}-tree;

.#{$prefix}-rtl,
.#{$prefix}-popover-rtl {
    .#{$module} {
        direction: rtl;
    }

    .#{$module}-wrapper {
        direction: rtl;
    }

    .#{$module}-option-list {
        direction: rtl;

        .#{$module}-option-expand-icon,
        .#{$module}-option-empty-icon {
            margin-right: 0;
