                // configurable, even when the source config object is frozen.
                return {
                    configurable: true,
                    enumerable: globalDescriptor.enumerable,
                    writable: true,
                    value: Reflect.get(defaultPropsFromGlobal, key),
                };
            }
            return targetDescriptor;
        }
    });
