        </span>;
    };


    return (
        <div className={`${prefixCls}-wrapper`}>
            {props.steps.map((item: Step, index) => {
                const { summary, status, actions } = item;
                const isOpen = openIndexes.has(index);
                const actionsLength = actions?.length;
                return (
                    <React.Fragment key={index}>
                        <div 
                            className={`${prefixCls}`}
                            role="button"
                            tabIndex={0}
                            onClick={() => toggleOpen(index)}
                            onKeyDown={e => {
                                if (e.key === 'Enter' || e.key === ' ') {
                                    e.preventDefault();
                                    toggleOpen(index);
                                }
                            }}
                        >
                            <div className={`${prefixCls}-prefix`}>
                                {
                                    status === 'completed' ? completedIcon() : loadingIcon()
                                }
                            </div>
                            <div className={`${prefixCls}-summary`}>{summary}</div>
                            {
                                actionsLength > 0 && (
                                    <div className={`${prefixCls}-suffix`}>
                                        {isOpen ? <IconChevronUp /> : <IconChevronDown />}
                                    </div>
                                )
                            }
                        </div>
                        <Collapsible isOpen={isOpen}>
                            <div className={`${prefixCls}-panel`}>
                                <div className={`${prefixCls}-line`} />
                                <div className={`${prefixCls}-action-wrapper`}>
                                    {actions?.map((action, i) => (
                                        <div 
                                            key={i}
                                            className={`${prefixCls}-action`}
                                        >
                                            <div className={`${prefixCls}-action-summary`}>{action.summary}</div>
                                            <div className={`${prefixCls}-action-desc`}>
                                                {action.icon}
                                                {action.description}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </Collapsible>
                    </React.Fragment>
                );
            })}
        </div>
    );
};

import React, { useState, useCallback } from 'react';
import Collapsible from '../../../collapsible';
import { cssClasses } from '@douyinfe/semi-foundation/aiChatDialogue/constants';
import { IconChevronDown, IconChevronUp, IconAISearchLevel2 } from '@douyinfe/semi-icons';
import MarkdownRender from '../../../markdownRender';
import { MarkdownRenderProps } from '../../../aiChatDialogue/interface';
import LocaleConsumer from '../../../locale/localeConsumer';
import { Locale } from "../../../locale/interface";


export interface ReasoningWidgetProps {
    status?: string;
    summary?: { text?: string; type?: string }[];
    content?: { text?: string; type?: string }[];
    markdownRenderProps?: MarkdownRenderProps;
    customRenderer?: (props: ReasoningWidgetProps) => React.ReactNode
}

const prefixCls = cssClasses.PREFIX_REASONING;

export const ReasoningWidget = (props: ReasoningWidgetProps) => {
    const { status, summary, content, markdownRenderProps, customRenderer } = props;
    const defaultOpen = status !== 'completed';
    const [isOpen, setIsOpen] = useState(defaultOpen);

    const handleClick = useCallback(() => {
        setIsOpen(!isOpen);
    }, [isOpen]);

    const getText = useCallback(() => {
        if (summary && summary.length > 0) {
            return summary.map((item: { text?: string; type?: string }) => item.text).join('\n');
        } else if (content && content.length > 0) {
            return content.map((item: { text?: string; type?: string }) => item.text).join('\n');
        }
        return '';
    }, [summary, content]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLDivElement>) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleClick();
        }
    }, [handleClick]);

    return (
        <div 
            role="button"
            tabIndex={0}
            className={`${prefixCls}-wrapper`} 
            onClick={handleClick}
            onKeyDown={handleKeyDown}
        >
            <div className={`${prefixCls}-header`}>
                <div className={`${prefixCls}-header-prefix`}>
                    <IconAISearchLevel2 />
                </div>
                <div className={`${prefixCls}-header-title`}>
                    <LocaleConsumer<Locale["AIChatDialogue"]> componentName="AIChatDialogue" >
                        {(locale: Locale["AIChatDialogue"]) => (status === 'completed' ? locale['reasoning']['completed'] : locale['reasoning']['thinking'])}
                    </LocaleConsumer>
                </div>
                <div className={`${prefixCls}-header-suffix`}>
                    {isOpen ? <IconChevronUp onClick={handleClick}/> : <IconChevronDown onClick={handleClick}/>}
                </div>
            </div>
            <Collapsible 
                isOpen={isOpen}
            >
                <div className={`${prefixCls}-content`}>
                    {customRenderer ? customRenderer(props) : (
                        <MarkdownRender
                            format='md'
                            raw={getText()}
                            {...markdownRenderProps}
                        />
                    )}
                </div>
            </Collapsible>
        </div>
    );
};

import React from 'react';
import { cssClasses, strings } from '@douyinfe/semi-foundation/aiChatDialogue/constants';
import { IconCode, IconWord, IconExcel, IconPdf, IconSendMsgStroked, IconVideo } from '@douyinfe/semi-icons';
import { Reference } from '@douyinfe/semi-foundation/aiChatDialogue/foundation';
import { Image } from '../../../index';
import cls from 'classnames';


export interface ReferenceWidgetProps {
    references: Reference[]
}

const prefixCls = cssClasses.PREFIX_REFERENCES;
const referencePrefixCls = cssClasses.PREFIX_REFERENCE;
const { DOCUMENT_TYPES, IMAGE_TYPES, PDF_TYPES, EXCEL_TYPES, CODE_TYPES, VIDEO_TYPES } = strings;

export const ReferenceWidget = (props: ReferenceWidgetProps) => {

    const { references } = props;

    const renderReferenceIcon = (name: string) => {
        if (name) {
            const extension = name.split('.').pop();
            let icon = null;
            let type = '';
            if (DOCUMENT_TYPES.includes(extension)) {
                icon = <IconWord size="small"/>;
                type = 'word';
            } else if (PDF_TYPES.includes(extension)) {
                icon = <IconPdf size="small"/>;
                type = 'pdf';
            } else if (EXCEL_TYPES.includes(extension)) {
                icon = <IconExcel size="small"/>;
                type = 'excel';
            } else if (CODE_TYPES.includes(extension)) {
                icon = <IconCode size="small"/>;
                type = 'code';
            } else if (VIDEO_TYPES.includes(extension)) {
                icon = <IconVideo size="small"/>;
                type = 'video';
            }

            return icon && <span className={cls(`${referencePrefixCls}-icon`, {
                [`${referencePrefixCls}-icon-${type}`]: type,
            })}>{icon}</span>;
        }
        return null;
    };

    const isImage = (name: string) => {
        if (name) {
            const extension = name.split('.').pop();
            return IMAGE_TYPES.includes(extension);
        }
        return false;
    };

    const renderReferenceImage = (reference: Reference) => {
        if (reference.url && isImage(reference.name)) {
            return <Image className={`${referencePrefixCls}-img`} src={reference.url} width={16} height={16} />;
        }
        return null;
    };

    return (
        <div 
            className={prefixCls} 
        >
            {references.map((reference) => (
                // todo: 确认背景色和一行分布几个
                <div className={referencePrefixCls} key={reference.id}>
                    <IconSendMsgStroked />
                    <span className={`${referencePrefixCls}-content`}>
                        {renderReferenceIcon(reference.name)}
                        {renderReferenceImage(reference)}
                        <span className={`${referencePrefixCls}-name`}>{reference.name || reference.content}</span>
                    </span>
                </div>
            ))}
        </div>
    );
};

import React, { ReactNode } from 'react';
import { AIChatDialogueActionProps, DefaultActionNodeObj } from '../interface';
import { IconThumbUpStroked, 
    IconDeleteStroked, 
    IconShareStroked,
    IconCopyStroked, 
    IconLikeThumb, 
    IconRedoStroked,
    IconEditStroked,
    IconMoreStroked
} from '@douyinfe/semi-icons';
import BaseComponent from '../../_base/baseComponent';
import { Button, Dropdown, Modal, Toast } from '../../index';
import copy from 'copy-text-to-clipboard';
import { cssClasses, strings } from '@douyinfe/semi-foundation/aiChatDialogue/constants';
import DialogueActionFoundation, { DialogueActionAdapter } from '@douyinfe/semi-foundation/aiChatDialogue/actionFoundation';
import LocaleConsumer from "../../locale/localeConsumer";
import { Locale } from "../../locale/interface";
import cls from 'classnames';

const { PREFIX_ACTION } = cssClasses;
const { ROLE, STATUS } = strings;

interface AIChatDialogueActionState {
    visible: boolean;
    showAction: boolean
}

class DialogueAction extends BaseComponent<AIChatDialogueActionProps, AIChatDialogueActionState> {

    copySuccessNode: ReactNode;
    foundation: DialogueActionFoundation;
    containerRef: React.RefObject<HTMLDivElement>;
    dropdownTriggerRef: React.RefObject<HTMLSpanElement>;
    clickOutsideHandler: any;

    constructor(props: AIChatDialogueActionProps) {
        super(props);
        this.foundation = new DialogueActionFoundation(this.adapter);
        this.state = {
            visible: false,
            showAction: false,
        };
        this.copySuccessNode = null;
        this.clickOutsideHandler = null;
        this.containerRef = React.createRef<HTMLDivElement>();
        this.dropdownTriggerRef = React.createRef<HTMLSpanElement>();
    }

    componentDidMount(): void {
        this.copySuccessNode = <LocaleConsumer<Locale["AIChatDialogue"]> componentName="AIChatDialogue" >
            {(locale: Locale["AIChatDialogue"]) => locale['copySuccess']}
        </LocaleConsumer>;
    }

    get adapter(): DialogueActionAdapter<AIChatDialogueActionProps, AIChatDialogueActionState> {
        return {
            ...super.adapter,
            notifyMessageCopy: () => {
                const { message, onMessageCopy } = this.props;
                onMessageCopy?.(message);
            },
            copyToClipboardAndToast: () => {
                const { message } = this.props;
                if (typeof message?.content === 'string') {
                    copy(message.content);
                } else if (Array.isArray(message?.content)) {
                    const content = message.content?.map(item => {
                        if (typeof (item as any)?.content === 'string') {
                            return (item as any)?.content;
                        } else {
                            return (item as any)?.content?.map(innerItem => innerItem?.text).join('');
                        }
                    }).join('');
                    copy(content);
                }
                Toast.success({
                    content: this.copySuccessNode
                });
            },
            notifyLikeMessage: () => {
                const { message, onMessageGoodFeedback } = this.props;
                onMessageGoodFeedback?.(message);
            },
            notifyDislikeMessage: () => {
                const { message, onMessageBadFeedback } = this.props;
                onMessageBadFeedback?.(message);
            },
            notifyResetMessage: () => {
                const { message, onMessageReset } = this.props;
                onMessageReset?.(message);
            },
            notifyShareMessage: () => {
                const { message, onMessageShare } = this.props;
                onMessageShare?.(message);
            },
            notifyEditMessage: () => {
                const { message, onMessageEdit } = this.props;
                onMessageEdit?.(message);
            },
            notifyDeleteMessage: () => {
                const { message, onMessageDelete } = this.props;
                onMessageDelete?.(message);
            },
            setVisible: (visible: boolean) => {
                this.setState({ visible });
            },
            setShowAction: (showAction: boolean) => {
                this.setState({ showAction });
            },
            registerClickOutsideHandler: (cb: () => void) => {
                if (this.clickOutsideHandler) {
                    this.adapter.unregisterClickOutsideHandler();
                }
                this.clickOutsideHandler = (e: React.MouseEvent): any => {
                    let el = this.dropdownTriggerRef && this.dropdownTriggerRef.current;
                    const target = e.target as Element;
                    const path = (e as any).composedPath && (e as any).composedPath() || [target];
                    if (
                        el && !(el as any).contains(target) && 
                        ! path.includes(el)
                    ) {
                        cb();
                    }
                };
                window.addEventListener('mousedown', this.clickOutsideHandler);
            },
            unregisterClickOutsideHandler: () => {
                if (this.clickOutsideHandler) {
                    window.removeEventListener('mousedown', this.clickOutsideHandler);
                    this.clickOutsideHandler = null;
                }
            },
        };
    }

    showDeleteModal = () => {
        Modal.warning({ title: <LocaleConsumer<Locale["AIChatDialogue"]> componentName="AIChatDialogue" >
            {(locale: Locale["AIChatDialogue"]) => locale['deleteConfirm']}
        </LocaleConsumer>, content: <LocaleConsumer<Locale["AIChatDialogue"]> componentName="AIChatDialogue" >
            {(locale: Locale["AIChatDialogue"]) => locale['deleteContent']}
        </LocaleConsumer>, onOk: this.foundation.deleteMessage });
        this.foundation.hideMoreDropdown();
    }

    copyNode = () => {
        return <Button
            key={'copy'}
            theme='borderless'
            icon={<IconCopyStroked />}
            type='tertiary'
            onClick={this.foundation.copyMessage}
            className={`${PREFIX_ACTION}-btn`}
        />;
    }

    resetNode = () => {
        return <Button
            key={'reset'}
            theme='borderless'
            icon={<IconRedoStroked className={`${PREFIX_ACTION}-icon-redo`}/>}
            type='tertiary'
            onClick={this.foundation.resetMessage}
            className={`${PREFIX_ACTION}-btn`}
        />;
    }

    shareNode = () => {
        return <Button
            key={'share'}
            theme='borderless'
            icon={<IconShareStroked />}
            type='tertiary'
            onClick={this.foundation.shareMessage}
        />;
    }


    likeNode = () => {
        const { message } = this.props;
        const { like } = message;
        return <Button
            key={'like'}
            theme='borderless'
            icon={like ? <IconLikeThumb /> : <IconThumbUpStroked /> }
            type='tertiary'
            className={`${PREFIX_ACTION}-btn`}
            onClick={() => this.foundation.likeMessage()}
        />;
    }

    dislikeNode = () => {
        const { message } = this.props;
        const { dislike } = message;
        return <Button
            theme='borderless'
            key={'dislike'}
            icon={dislike ? <IconLikeThumb className={`${PREFIX_ACTION}-icon-flip`} /> : <IconThumbUpStroked className={'semi-chat-chatBox-action-icon-flip'} />}
            type='tertiary'
            className={`${PREFIX_ACTION}-btn`}
            onClick={() => this.foundation.dislikeMessage()}
        />;
    }

    editNode = () => {
        // todo: 支持多模态消息编辑，需要使用 aiChatInput 组件
        return <Button
            key={'edit'}
            theme='borderless'
            icon={<IconEditStroked />}
            type='tertiary'
            onClick={() => this.foundation.editMessage()}
        />;
    }



    moreNode = () => {
        return (
            <Dropdown
                trigger="custom"
                position='bottomLeft'
                className={`${PREFIX_ACTION}-dropdown`}
                visible={this.state.visible}
                onCancel={this.foundation.hideMoreDropdown}
                spacing={12}
                stopPropagation
                render={
                    <Dropdown.Menu>
                        <Dropdown.Item onClick={() => this.showDeleteModal()}>
                            <IconDeleteStroked /> <LocaleConsumer<Locale["AIChatDialogue"]> componentName="AIChatDialogue" >
                                {(locale: Locale["AIChatDialogue"]) => locale['delete']}
                            </LocaleConsumer>
                        </Dropdown.Item>
                    </Dropdown.Menu>
                }
            >
                <span 
                    ref={this.dropdownTriggerRef}
                >
                    <Button
                        key={'more'}
                        theme='borderless'
                        icon={<IconMoreStroked />}
                        type='tertiary'
                        onClick={this.foundation.showMoreDropdown}
                    />
                </span>
            </Dropdown>)
        ;
    }

    render() {
        const { message, isLastChat } = this.props;
        const { showAction } = this.state;
        const { role, status = STATUS.COMPLETED } = message;
        const completed = status === STATUS.COMPLETED ;
        const showFeedback = role !== ROLE.USER && completed;
        const showReset = isLastChat && role === ROLE.ASSISTANT;
        const finished = status !== STATUS.IN_PROGRESS && status !== STATUS.INCOMPLETE;
        const showEdit = role === ROLE.USER;

        const wrapCls = cls(PREFIX_ACTION, { 
            [`${PREFIX_ACTION}-show`]: showReset && finished || showAction,
            [`${PREFIX_ACTION}-hidden`]: !finished
        });

        const { customRenderFunc } = this.props;
        if (customRenderFunc) {
            const actionNodes = [];
            const actionNodeObj = {} as DefaultActionNodeObj;
            if (completed) {
                const copyNode = this.copyNode();
                actionNodes.push(copyNode);
                actionNodeObj.copyNode = copyNode;
            }
            if (showFeedback) {
                const likeNode = this.likeNode();
                actionNodes.push(likeNode);
                actionNodeObj.likeNode = likeNode;
                const dislikeNode = this.dislikeNode();
                actionNodes.push(dislikeNode);
                actionNodeObj.dislikeNode = dislikeNode;
            }
            if (showReset) {
                const resetNode = this.resetNode();
                actionNodes.push(resetNode);
                actionNodeObj.resetNode = resetNode;
            }
            const moreNode = this.moreNode();
            actionNodes.push(moreNode);
            actionNodeObj.moreNode = moreNode;
            return customRenderFunc({
                message,
                defaultActions: actionNodes,
                className: wrapCls,
                defaultActionsObj: actionNodeObj
            });
        }

        return <div className={wrapCls} ref={this.containerRef}>
            {completed && this.copyNode()}
            {showReset && this.resetNode()}
            {completed && this.shareNode()}
            {showEdit && this.editNode()}
            {showFeedback && this.likeNode()}
            {showFeedback && this.dislikeNode()}
            {this.moreNode()}
        </div>;
    }
}

export default DialogueAction;

