interface FileAttachmentProps extends InputFile {
    onFileClick?: (file: InputFile) => void;
    disabledFileItemClick?: boolean;
    role?: string;
    showReference?: boolean;
    onReferenceClick?: (item: Reference ) => void;
    isLastFile?: boolean
