        const component = {
            month: (<MonthCalendar />),
            week: (<WeekCalendar />),
            day: (<DayCalendar />),
            range: (<RangeCalendar />)
        };
        return React.cloneElement(component[mode], { ...rest });
    }
}

export type { EventObject };
