    } = props;
    const { renderChatBoxAvatar, renderChatBoxAction, 
        renderChatBoxContent, renderChatBoxTitle,
        renderFullChatBox
    } = chatBoxRenderConfig;

    const continueSend = useMemo(() => {
        return message?.role === previousMessage?.role;
    }, [message.role, previousMessage]);

