            error: <IconAlertCircle size="large"/>,
        };
        let iconType = iconMap[type];
        const iconCls = cls({
            [`${prefixCls}-icon`]: true,
            [`${prefixCls}-${type}`]: true,
        });
        if (icon) {
            iconType = icon;
        }
        if (iconType) {
            return (
                <div className={iconCls} x-semi-prop="icon">
