            onClick: disabled ? null : this.onClick,
            onKeyDown: disabled ? null : this.onKeyDown,
            onMouseMove: disabled ? null : this.onHover,
            className: starWrapCls,
        };
        const AriaSetSize = allowHalf ? count * 2 + 1 : count + 1;
