                    >
                        {handleDot?.[0] && <div className={cssClasses.HANDLE_DOT} style={{
                            ...(handleDot[0]?.size ? { width: handleDot[0].size, height: handleDot[0].size } : {}),
                            ...(handleDot[0]?.color ? { backgroundColor: handleDot[0].color } : {}),
